-- Movimiento aditivo -- SIN DELETE, idempotente por id (ON CONFLICT DO NOTHING:
-- si ya existe un id igual, no se duplica ni se sobreescribe silenciosamente).
DO $$
DECLARE rc integer;
BEGIN
  INSERT INTO biblioteca_vectores (id, coleccion, materia, contenido, num_articulo, fuente, metadata, embedding, jurisdiccion, fuente_tipo, es_norma_vigente)
  SELECT id, coleccion, materia, contenido, num_articulo, fuente, metadata, embedding, jurisdiccion, fuente_tipo, es_norma_vigente
  FROM stg_ley_propiedad_82_2004
  ON CONFLICT (id) DO NOTHING;
  GET DIAGNOSTICS rc = ROW_COUNT;
  IF rc = 0 THEN
    RAISE NOTICE 'Cero filas insertadas -- probable colisión total de ids con filas ya existentes; revisar antes de asumir éxito';
  END IF;
END $$;

DROP TABLE stg_ley_propiedad_82_2004;
